/* A website's drafts and preview link private (round AX, run any time). WHY: the public read policies of the website builder (sti_select_published, sts_select_published and stp_select_published, made by migration 20260407 for anon AND authenticated) let the anon key, which is in every page Storelib serves, and any signed in account read three private columns of every published website through the REST API: store_theme_installs.preview_token (the secret that opens the owner's unpublished preview at /w/{name}/preview/{token}), store_theme_settings.draft_settings and store_theme_pages.draft_sections (the creator's unpublished edits: launches, prices, pages not yet live). Row level security cannot hide a column, so this part does it with grants, as big platforms do: the public key reads published data only, and drafts and the preview token are read by the owner (their own session, through the owner policies) and by the server (the service role, which the live site, previews, sitemaps, the editor for team members and every other reader in the app use: the app reads none of these three columns with the anon key, and no signed in session reads another creator's website). WHAT IT DOES, for each of the three tables that exists: 1. makes sure the owner can still read their own rows: when no SELECT policy for the owner (one whose USING reads auth.uid()) exists, <table>_owner_select is created for authenticated. 2. narrows every public read policy (a permissive SELECT policy whose USING reads published and reads neither auth. nor team_) from anon and authenticated to anon only, with a notice naming it, so a signed in stranger reads nothing of another creator's website; any other policy that does not read auth. is named in a notice and left alone. 3. when the anon key can read the private column, takes SELECT on the table from anon and gives SELECT back on every other column, so the published columns (sections, settings, status, the route facts the proxy reads) still answer the anon key and the private column is refused (permission denied); a column added later is private to anon until granted. It does NOT change any row, does not touch the owner's or the server's access, and does not change INSERT, UPDATE or DELETE. Takes a short lock on each table. A missing table or column is skipped with a notice. Safe to run again: a second run finds the owner policies there, no public policy for authenticated and nothing the anon key can read, and changes nothing. To check: select has_column_privilege('anon', 'public.store_theme_installs', 'preview_token', 'SELECT'); select policyname, roles from pg_policies where tablename like 'store_theme_%'; */
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['store_theme_installs', 'store_theme_settings', 'store_theme_pages'] LOOP IF to_regclass('public.' || t) IS NULL THEN RAISE NOTICE 'part 463: public.% does not exist here, skipped', t; CONTINUE; END IF; IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = t AND p.permissive = 'PERMISSIVE' AND p.cmd IN ('SELECT', 'ALL') AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') ~ 'auth\.uid\(\)') THEN CONTINUE; END IF; IF t = 'store_theme_installs' AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t AND column_name = 'creator_id') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (creator_id IN (SELECT c.id FROM public.creators c WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_select', t); RAISE NOTICE 'part 463: created %_owner_select', t; ELSIF t <> 'store_theme_installs' AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t AND column_name = 'install_id') THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (install_id IN (SELECT i.id FROM public.store_theme_installs i JOIN public.creators c ON c.id = i.creator_id WHERE c.user_id = (SELECT auth.uid())))', t || '_owner_select', t); RAISE NOTICE 'part 463: created %_owner_select', t; ELSE RAISE NOTICE 'part 463: public.% has no owner read policy and no owner column, left alone', t; END IF; END LOOP; END $do$;
DO $do$ DECLARE t text; r record; narrowed int := 0; BEGIN FOREACH t IN ARRAY ARRAY['store_theme_installs', 'store_theme_settings', 'store_theme_pages'] LOOP IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; FOR r IN SELECT p.policyname, p.roles, p.qual FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = t AND p.permissive = 'PERMISSIVE' AND p.cmd = 'SELECT' AND p.roles && ARRAY['authenticated', 'public']::name[] AND coalesce(p.qual, '') !~ '(auth\.|team_)' ORDER BY p.policyname LOOP IF coalesce(r.qual, '') ~ 'published' THEN EXECUTE format('ALTER POLICY %I ON public.%I TO anon', r.policyname, t); narrowed := narrowed + 1; RAISE NOTICE 'part 463: policy "%" on % now for anon only (was %, using %)', r.policyname, t, r.roles, r.qual; ELSE RAISE NOTICE 'part 463: policy "%" on % (% using %) does not read the owner and is not a published read, left alone', r.policyname, t, r.roles, coalesce(r.qual, 'nothing'); END IF; END LOOP; END LOOP; RAISE NOTICE 'part 463: % public read policies narrowed to anon', narrowed; END $do$;
DO $do$ DECLARE t text; secret text; cols text; BEGIN FOREACH t IN ARRAY ARRAY['store_theme_installs:preview_token', 'store_theme_settings:draft_settings', 'store_theme_pages:draft_sections'] LOOP secret := split_part(t, ':', 2); t := split_part(t, ':', 1); IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t AND column_name = secret) THEN RAISE NOTICE 'part 463: public.%.% does not exist here, skipped', t, secret; CONTINUE; END IF; IF NOT has_column_privilege('anon', format('public.%I', t), secret, 'SELECT') THEN RAISE NOTICE 'part 463: the anon key already cannot read public.%.%', t, secret; CONTINUE; END IF; SELECT string_agg(format('%I', a.attname), ', ' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid = to_regclass('public.' || t) AND a.attnum > 0 AND NOT a.attisdropped AND a.attname <> secret; EXECUTE format('REVOKE SELECT ON public.%I FROM anon', t); EXECUTE format('GRANT SELECT (%s) ON public.%I TO anon', cols, t); IF has_column_privilege('anon', format('public.%I', t), secret, 'SELECT') THEN RAISE WARNING 'part 463: the anon key still reads public.%.% through a grant to PUBLIC; revoke it by hand after checking who uses it', t, secret; ELSE RAISE NOTICE 'part 463: the anon key no longer reads public.%.%', t, secret; END IF; END LOOP; END $do$;
notify pgrst, 'reload schema';
